/* ============================ INTERACCIONES ============================ */
function initReveal(root){
  var els = root.querySelectorAll(".rv");
  if (!("IntersectionObserver" in window) || REDUCED){ els.forEach(function(e){ e.classList.add("in"); }); return; }
  var io = new IntersectionObserver(function(en){ en.forEach(function(e){ if (e.isIntersecting){ e.target.classList.add("in"); io.unobserve(e.target); } }); }, { rootMargin: "0px 0px -8% 0px", threshold: .08 });
  els.forEach(function(e){ io.observe(e); });
}
function initCount(root){
  var els = root.querySelectorAll("[data-to]");
  function run(el){
    var to = parseFloat(el.getAttribute("data-to")), dec = +el.getAttribute("data-dec") || 0, t0 = null, D = 1600;
    function fmt(v){ return dec ? v.toFixed(dec).replace(".", ",") : Math.round(v).toString().replace(/\B(?=(\d{3})+(?!\d))/g, "."); }
    if (REDUCED){ el.textContent = fmt(to); return; }
    function step(t){ if (!t0) t0 = t; var p = Math.min(1, (t - t0) / D), e = 1 - Math.pow(1 - p, 4); el.textContent = fmt(to * e); if (p < 1) requestAnimationFrame(step); }
    requestAnimationFrame(step);
  }
  if (!("IntersectionObserver" in window)){ els.forEach(run); return; }
  var io = new IntersectionObserver(function(en){ en.forEach(function(e){ if (e.isIntersecting){ run(e.target); io.unobserve(e.target); } }); }, { threshold: .4 });
  els.forEach(function(e){ io.observe(e); });
}
function initCarrusel(){
  var car = document.getElementById("vnh-car"); if (!car) return;
  var its = car.querySelectorAll(".h-it"), n = its.length, L = CFG.colores || [];
  if (!n) return;
  var p = colorIdx(), target = p, cur = -1, drag = null, touched = false, raf = 0;
  var cta = document.getElementById("vnh-cta"), nm = document.getElementById("vnh-cname"), pa = document.getElementById("vnh-cpara");
  var btns = document.querySelectorAll("#vnh-cols button");
  function mod(a){ return ((a % n) + n) % n; }
  function layout(){
    var W = car.clientWidth, R = W * (W > 480 ? .40 : .40), RZ = W > 480 ? 520 : 400;
    for (var i = 0; i < n; i++){
      var d = mod(i - p); if (d > n / 2) d -= n;
      var th = d * 2 * Math.PI / n, c = Math.cos(th), k = (c + 1) / 2;
      var it = its[i];
      it.style.transform = "translate3d(" + (Math.sin(th) * R).toFixed(1) + "px,0," + ((c - 1) * RZ).toFixed(1) + "px)";
      it.style.opacity = (0.12 + 0.88 * Math.pow(k, 1.6)).toFixed(3);
      it.style.zIndex = Math.round(10 + k * 10);
      it.style.filter = "brightness(" + (0.55 + 0.45 * k).toFixed(3) + ")";
      it.classList.toggle("front", Math.abs(d) < .5);
    }
    var ix = mod(Math.round(p));
    if (ix !== cur){ cur = ix; elegir(ix); }
  }
  function elegir(i){
    var c = L[i]; if (!c) return;
    if (nm){ nm.textContent = c.nombre; }
    if (pa){ pa.textContent = c.para || ""; }
    if (cta){ cta.href = link(c.match); cta.querySelector("span").textContent = "Quiero el " + c.nombre; }
    btns.forEach(function(b, j){ b.classList.toggle("on", j === i); b.setAttribute("aria-pressed", j === i ? "true" : "false"); });
    var st = document.querySelector("#vnh-sticky a"), si = document.querySelector("#vnh-sticky img");
    if (st) st.href = link(c.match); if (si) si.src = c.img;
  }
  function loop(){
    raf = 0;
    if (!drag){ var diff = target - p; if (Math.abs(diff) < .001){ p = target; layout(); return; } p += diff * .12; }
    layout(); raf = requestAnimationFrame(loop);
  }
  function kick(){ if (!raf) raf = requestAnimationFrame(loop); }
  function ir(t){ target = t; kick(); }
  function stop(){ touched = true; }
  /* flechas, colores y teclado */
  var mq = document.getElementById("vnh-media");
  mq.querySelector(".h-nav.pv").addEventListener("click", function(){ stop(); ir(Math.round(target) - 1); });
  mq.querySelector(".h-nav.nx").addEventListener("click", function(){ stop(); ir(Math.round(target) + 1); });
  btns.forEach(function(b){ b.addEventListener("click", function(){
    stop(); var i = +b.getAttribute("data-i"), d = mod(i - Math.round(target)); if (d > n / 2) d -= n; ir(Math.round(target) + d);
  }); });
  car.addEventListener("keydown", function(e){
    if (e.key === "ArrowLeft"){ e.preventDefault(); stop(); ir(Math.round(target) - 1); }
    if (e.key === "ArrowRight"){ e.preventDefault(); stop(); ir(Math.round(target) + 1); }
  });
  /* arrastre (mouse y dedo) */
  car.addEventListener("pointerdown", function(e){
    if (e.button && e.button !== 0) return;
    drag = { x: e.clientX, y: e.clientY, p: p, t: performance.now(), v: 0, lx: e.clientX, moved: false, id: e.pointerId, item: e.target.closest(".h-it") };
    stop();
  });
  window.addEventListener("pointermove", function(e){
    if (!drag || e.pointerId !== drag.id) return;
    var dx = e.clientX - drag.x;
    if (!drag.moved){
      if (Math.abs(dx) < 6) return;
      if (Math.abs(e.clientY - drag.y) > Math.abs(dx)){ drag = null; return; } /* scroll vertical: se lo dejamos a la página */
      drag.moved = true; car.classList.add("drag");
      try { car.setPointerCapture(e.pointerId); } catch (er) {}
    }
    var now = performance.now(), W = car.clientWidth || 300;
    drag.v = (e.clientX - drag.lx) / Math.max(1, now - drag.t); drag.lx = e.clientX; drag.t = now;
    p = drag.p - dx / (W * .55); layout();
  });
  function up(e){
    if (!drag || (e && e.pointerId !== drag.id)) return;
    var d = drag; drag = null; car.classList.remove("drag");
    if (!d.moved){
      if (d.item){ var i = +d.item.getAttribute("data-i"), k = mod(i - Math.round(p)); if (k > n / 2) k -= n; ir(Math.round(p) + k); }
      return;
    }
    var W = car.clientWidth || 300;
    ir(Math.round(p - d.v * 180 / (W * .55)));
  }
  window.addEventListener("pointerup", up); window.addEventListener("pointercancel", up);
  window.addEventListener("resize", layout);
  layout();
  /* giro solo, hasta que el cliente lo toca. Se frena fuera de pantalla. */
  if (CFG.autoGiro && !REDUCED){
    var visible = true;
    if ("IntersectionObserver" in window) new IntersectionObserver(function(en){ visible = en[0].isIntersecting; }, { threshold: .3 }).observe(car);
    var ti = setInterval(function(){
      if (touched){ clearInterval(ti); return; }
      if (visible && !document.hidden && !drag) ir(Math.round(target) + 1);
    }, 3200);
  }
}
function initTilt(){
  var media = document.getElementById("vnh-media"), tilt = document.getElementById("vnh-tilt");
  if (!media || !tilt || REDUCED) return;
  var hero = document.getElementById("vnh-hero");
  function set(x, y){ tilt.style.transform = "rotateY(" + (x * 9).toFixed(2) + "deg) rotateX(" + (-y * 6).toFixed(2) + "deg)"; }
  hero.addEventListener("pointermove", function(e){
    if (e.pointerType === "touch" || e.buttons) return;
    var r = media.getBoundingClientRect();
    set(Math.max(-1, Math.min(1, (e.clientX - r.left - r.width / 2) / (r.width / 2))), Math.max(-1, Math.min(1, (e.clientY - r.top - r.height / 2) / (r.height / 2))));
  });
  hero.addEventListener("pointerleave", function(){ set(0, 0); });
  /* en el celular, se mueve con la inclinación del teléfono (si el navegador lo permite sin pedir permiso) */
  if (window.DeviceOrientationEvent && typeof DeviceOrientationEvent.requestPermission !== "function"){
    var base = null;
    window.addEventListener("deviceorientation", function(e){
      if (e.gamma == null) return;
      if (base === null) base = e.beta || 0;
      set(Math.max(-1, Math.min(1, e.gamma / 25)), Math.max(-1, Math.min(1, ((e.beta || 0) - base) / 25)));
    });
  }
}
/* Cinta infinita de reseñas: la fila 1 corre a la derecha y la 2 a la izquierda.
   Se mueve SIEMPRE (también con "Reducir movimiento" activado en la compu),
   frena al pasar el mouse sin detenerse, y se puede arrastrar con el dedo. */
function initMarquee(root){
  var VEL = 42; /* píxeles por segundo */
  root.querySelectorAll(".mq-row").forEach(function(row){
    var tk = row.querySelector(".mq-tk"), base = tk.innerHTML, dir = row.classList.contains("rt") ? 1 : -1;
    var setW = 0, x = 0, speed = 1, target = 1, visible = true, drag = null, last = 0;
    function build(){
      tk.innerHTML = base;
      setW = tk.scrollWidth;
      if (!setW) return;
      var copies = Math.max(2, Math.ceil(row.clientWidth / setW) + 2), h = "";
      for (var i = 0; i < copies; i++) h += base;
      tk.innerHTML = h;
      tk.querySelectorAll(".rc").forEach(function(c, i){ if (i >= tk.children.length / copies) c.setAttribute("aria-hidden", "true"); });
      x = dir > 0 ? -setW : 0; wrap(); paint();
    }
    function wrap(){ if (!setW) return; while (x <= -setW) x += setW; while (x > 0) x -= setW; }
    function paint(){ tk.style.transform = "translate3d(" + x.toFixed(2) + "px,0,0)"; }
    function frame(t){
      var dt = last ? Math.min(.05, (t - last) / 1000) : 0; last = t;
      if (visible && !drag && setW){
        speed += (target - speed) * Math.min(1, dt * 4);
        x += dir * VEL * speed * dt; wrap(); paint();
      }
      requestAnimationFrame(frame);
    }
    row.addEventListener("mouseenter", function(){ target = .2; });
    row.addEventListener("mouseleave", function(){ target = 1; });
    row.addEventListener("pointerdown", function(e){
      if (e.button && e.button !== 0) return;
      drag = { sx: e.clientX, sy: e.clientY, x0: x, on: false, id: e.pointerId };
    });
    window.addEventListener("pointermove", function(e){
      if (!drag || e.pointerId !== drag.id) return;
      var dx = e.clientX - drag.sx;
      if (!drag.on){
        if (Math.abs(dx) < 6) return;
        if (Math.abs(e.clientY - drag.sy) > Math.abs(dx)){ drag = null; return; }
        drag.on = true; row.classList.add("drag");
        try { row.setPointerCapture(e.pointerId); } catch (er) {}
      }
      x = drag.x0 + dx; wrap(); paint();
    });
    function up(e){ if (drag && (!e || e.pointerId === drag.id)){ drag = null; row.classList.remove("drag"); } }
    window.addEventListener("pointerup", up); window.addEventListener("pointercancel", up);
    if ("IntersectionObserver" in window) new IntersectionObserver(function(en){ visible = en[0].isIntersecting; }, { rootMargin: "100px" }).observe(row);
    var rt; window.addEventListener("resize", function(){ clearTimeout(rt); rt = setTimeout(build, 200); });
    if (document.fonts && document.fonts.ready) document.fonts.ready.then(build);
    build(); requestAnimationFrame(frame);
  });
}
function initPasos(){
  var list = document.getElementById("vnh-pslist"); if (!list) return;
  var line = list.querySelector(".ps-line i"), items = list.querySelectorAll(".ps-it"), ticking = false;
  function upd(){
    ticking = false;
    var r = list.getBoundingClientRect(), mid = innerHeight * .62;
    var p = Math.max(0, Math.min(1, (mid - r.top) / r.height));
    line.style.setProperty("--p", (p * 100).toFixed(1) + "%");
    items.forEach(function(it){ var ir = it.getBoundingClientRect(); it.classList.toggle("on", ir.top + 29 < mid); });
  }
  window.addEventListener("scroll", function(){ if (!ticking){ ticking = true; requestAnimationFrame(upd); } }, { passive: true });
  window.addEventListener("resize", upd); upd();
}
function initAntes(){
  var box = document.getElementById("vnh-ba"); if (!box) return;
  var top = box.querySelector(".ba-top"), h = box.querySelector(".ba-h"), rg = box.querySelector(".ba-range");
  function set(v){ top.style.clipPath = "inset(0 " + (100 - v) + "% 0 0)"; h.style.left = v + "%"; }
  rg.addEventListener("input", function(){ set(rg.value); }); set(50);
}
function initVideos(){
  var row = document.getElementById("vnh-vd"); if (!row) return;
  row.querySelectorAll(".vd-it").forEach(function(it){
    var v = it.querySelector("video");
    it.addEventListener("click", function(){
      if (v.paused){
        row.querySelectorAll("video").forEach(function(o){ if (o !== v){ o.pause(); o.parentNode.classList.remove("pl"); } });
        v.muted = false; var p = v.play(); if (p && p.catch) p.catch(function(){ v.muted = true; v.play(); });
        it.classList.add("pl");
      } else { v.pause(); it.classList.remove("pl"); }
    });
  });
}
function initSticky(){
  var hero = document.getElementById("vnh-hero"), fin = document.getElementById("vnh-final");
  if (!hero || !("IntersectionObserver" in window)) return;
  var bar = document.createElement("div"); bar.id = "vnh-sticky";
  bar.innerHTML = '<img src="' + esc(imgPrincipal()) + '" alt=""><div><b>' + esc(MARCA) + " · Shampoo Cubre Canas</b><small>Envío gratis · 30 días de garantía</small></div><a href=\"" + esc(link()) + '">Elegir color</a>';
  document.body.appendChild(bar);
  var heroOut = false, finIn = false;
  function upd(){ bar.classList.toggle("on", heroOut && !finIn); }
  new IntersectionObserver(function(e){ heroOut = !e[0].isIntersecting; upd(); }, { threshold: 0 }).observe(hero);
  /* se esconde al llegar al cierre y en el footer */
  if (fin) new IntersectionObserver(function(e){ finIn = e[0].isIntersecting || e[0].boundingClientRect.top < 0; upd(); }, { threshold: .2 }).observe(fin);
}

/* ================================ MONTAJE ================================ */
function montar(){
  if (document.getElementById("vnh-root")) return;
  var root = document.createElement("div"); root.id = "vnh-root";
  root.innerHTML = sBar() + sHero() + sNumeros() + sMarquesina() + sFotos() + sAntes() + sVs() + sPasos() + sVideos() + sCombos() + sGarantia() + sFaq() + sFinal() + (CFG.footerPropio ? sFooter() : "");

  /* Va en el lugar del inicio nativo: justo antes de su primera sección.
     Si el tema no tiene ninguna, va debajo del header. */
  var first = document.querySelector("[data-store^='home-'], .js-home-main-slider, .section-home, .section-banners-home");
  if (first && first.parentNode){
    first.parentNode.insertBefore(root, first);
  } else {
    var head = document.querySelector(".js-head-main, header"), anchor = head;
    while (anchor && anchor.parentNode && anchor.parentNode !== document.body) anchor = anchor.parentNode;
    if (anchor && anchor.parentNode) anchor.parentNode.insertBefore(root, anchor.nextSibling);
    else document.body.insertBefore(root, document.body.firstChild);
    /* si el header es fijo y tapa el inicio, lo compensa */
    if (head){
      var hs = getComputedStyle(head);
      if (hs.position === "fixed"){ var gap = head.getBoundingClientRect().bottom - root.getBoundingClientRect().top; if (gap > 0) root.style.paddingTop = gap + "px"; }
    }
  }
  initReveal(root); initCount(root); initTilt(); initSticky(); initCarrusel(); initMarquee(root); initPasos(); initAntes(); initVideos();
  var up = root.querySelector(".ft-up"); if (up) up.addEventListener("click", function(){ window.scrollTo({ top: 0, behavior: REDUCED ? "auto" : "smooth" }); });
}
onReady(montar);

